/**
 * llm-wiki for OpenCode v2 — Code Mode plugin (GENERATED by build/build.mjs from
 * core/llm-wiki.mjs; edit the core, not this file).
 *
 * Registers the `wiki.*` tools that operate a local, self-maintaining markdown
 * knowledge base (Karpathy LLM Wiki pattern): scaffold/attach a workspace,
 * search/read pages, validated page writes with auto index rebuild, source
 * ingest tracking, structural lint, log, no-git snapshot backup, optional git
 * commit. Deterministic operations only — no network, no API keys. Page
 * content is authored by the host agent following the workspace AGENTS.md schema.
 */
import { Plugin } from "@opencode/plugin"

// ---------------------------------------------------------------------------
// core: single source of truth (embedded by build)
// ---------------------------------------------------------------------------
__CORE__
// ---------------------------------------------------------------------------

const asText = (content: string) => ({ content })

export default Plugin.define({
  id: "llm-wiki",
  async setup(ctx) {
    await ctx.tool.transform((editor) => {
      editor.namespace({
        name: "wiki",
        description: "Local LLM Wiki: a self-maintaining markdown knowledge base (raw sources + generated pages + deterministic search/lint/index/backup). Read the workspace AGENTS.md for the ingest/query/lint workflows.",
      })
      for (const tool of TOOLS) {
        editor.add({
          name: tool.name.replace(/^wiki_/, ""),
          description: tool.description,
          input: tool.schema,
          options: { namespace: "wiki", codemode: true },
          execute: async (input: unknown) => {
            try {
              return asText(String(tool.run((input ?? {}) as Record<string, unknown>)))
            } catch (error) {
              throw new Error(error instanceof Error ? error.message : String(error))
            }
          },
        })
      }
    })
  },
})
